      "citations": [
        {
          "index": 7,
          "quote": "The disadvantage is that strict MVCC semantics are violated."
        }
      ]
    },
    {
      "claim_text": "Installations with extremely high update rates may vacuum their busiest tables as often as every few minutes.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that some installations with extremely high update rates vacuum their busiest tables as often as once every few minutes.",
      "citations": [
        {
          "index": 5,
          "quote": "Some installations with extremely high update rates vacuum their busiest tables as often as once every few minutes."
        }
      ]
    },
    {
      "claim_text": "Anyone not using autovacuum is required to run a database-wide VACUUM once a day.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passage describes a database-wide daily VACUUM as a typical approach for those not using autovacuum, not as a requirement.",
      "citations": []
    }
  ]
